def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # Map id -> (side, price, arrival_time, original_qty, remaining_qty) for active orders
    cancelled = set()
    arrival_time_counter = [0]

    def add_to_buy_book(price, id, qty):
        arrival_time = arrival_time_counter[0]
        arrival_time_counter[0] += 1
        buy_book.append([price, arrival_time, id, qty])
        buy_book.sort(key=lambda x: (-x[0], x[1]))

    def add_to_sell_book(price, id, qty):
        arrival_time = arrival_time_counter[0]
        arrival_time_counter[0] += 1
        sell_book.append([price, arrival_time, id, qty])
        sell_book.sort(key=lambda x: (x[0], x[1]))

    def match_buy(id, price, qty, is_market=False):
        remaining = qty
        while remaining > 0 and sell_book:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
            if not is_market and sell_price > price:
                break
            if is_market or sell_price <= price:
                trade_qty = min(remaining, sell_qty)
                trades.append([id, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                sell_book[0][3] -= trade_qty
                if sell_book[0][3] == 0:
                    sell_book.pop(0)
            else:
                break
        return remaining

    def match_sell(id, price, qty, is_market=False):
        remaining = qty
        while remaining > 0 and buy_book:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
            if not is_market and buy_price < price:
                break
            if is_market or buy_price >= price:
                trade_qty = min(remaining, buy_qty)
                trades.append([buy_id, id, buy_price, trade_qty])
                remaining -= trade_qty
                buy_book[0][3] -= trade_qty
                if buy_book[0][3] == 0:
                    buy_book.pop(0)
            else:
                break
        return remaining

    for order in orders:
        order_type = order[0]

        if order_type == 'cancel':
            id = order[1]
            if id in order_map:
                side, price, arrival_time, original_qty, remaining_qty = order_map[id]
                if remaining_qty > 0:
                    cancelled.add(id)
                    if side == 'buy':
                        buy_book[:] = [x for x in buy_book if x[2] != id]
                    else:
                        sell_book[:] = [x for x in sell_book if x[2] != id]
                del order_map[id]

        elif order_type == 'limit':
            id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]

            arrival_time = arrival_time_counter[0]

            if side == 'buy':
                remaining = match_buy(id, price, qty, is_market=False)
                if remaining > 0:
                    add_to_buy_book(price, id, remaining)
                    order_map[id] = (side, price, arrival_time, qty, remaining)
            else:  # sell
                remaining = match_sell(id, price, qty, is_market=False)
                if remaining > 0:
                    add_to_sell_book(price, id, remaining)
                    order_map[id] = (side, price, arrival_time, qty, remaining)

        elif order_type == 'ioc':
            id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]

            if side == 'buy':
                match_buy(id, price, qty, is_market=False)
            else:  # sell
                match_sell(id, price, qty, is_market=False)

        elif order_type == 'market':
            id = order[1]
            side = order[2]
            qty = order[3]

            if side == 'buy':
                match_buy(id, float('inf'), qty, is_market=True)
            else:  # sell
                match_sell(id, 0, qty, is_market=True)

    return trades

